SELECT f.mix_area, f.glue, f.machine_code FROM T_FORMULA_MACHINE f INNER JOIN T_MIX_MACHINE m ON f.machine_code = m.machine_code and m.status = '0'and m.del_flag = '0' AND (m.mid_status = '0' OR m.night_status = '0' OR m.day_status = '0') WHERE f.DEL_FLAG= '0'
AND f.MIX_AREA = #{mixArea}
order by f.mix_area, f.glue, f.machine_order desc

